package com.himeros.notification;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity@Table(name="notifications")class Notification{@Id private UUID id;@Column(name="user_id",nullable=false)private UUID userId;@Column(nullable=false)private String type;@Column(nullable=false,length=160)private String title;@Column(nullable=false,length=500)private String body;@Column(name="data_json",columnDefinition="text")private String dataJson;@Column(name="read_at")private Instant readAt;@Column(name="created_at",nullable=false)private Instant createdAt;protected Notification(){}Notification(UUID user,String type,String title,String body,String data){id=UUID.randomUUID();userId=user;this.type=type;this.title=title;this.body=body;dataJson=data;createdAt=Instant.now();}UUID id(){return id;}UUID user(){return userId;}String type(){return type;}String title(){return title;}String body(){return body;}String data(){return dataJson;}Instant read(){return readAt;}Instant created(){return createdAt;}void markRead(){if(readAt==null)readAt=Instant.now();}}
